export type Monster =
  | 'sphinx'
  | 'undead-warrior'
  | 'zombie'
  | 'hydra'
  | 'cyclops'
  | 'orthrus'
  | 'chimera';

export interface Card {
  monster: Monster;
  /** Point variant of an Undead Warrior. Does not affect its type. */
  rank?: 1 | 2 | 3;
}

/**
 * Sphinx — 1 point. 2 per type beyond three, else 1.
 *
 * A type is a distinct monster. The Sphinx counts itself, and the three
 * Undead Warrior ranks are one type between them, so `rank` is ignored here.
 */
const TYPE_THRESHOLD = 3;

function sphinxValue(typeCount: number): number {
  const beyondThreshold = typeCount - TYPE_THRESHOLD;

  return 1 + (beyondThreshold > 0 ? 2 * beyondThreshold : 1);
}

export function scoreArmy(army: readonly Card[]): number {
  const sphinxCount = army.filter((card) => card.monster === 'sphinx').length;

  if (sphinxCount === 0) {
    return 0;
  }

  const typeCount = new Set(army.map((card) => card.monster)).size;

  return sphinxCount * sphinxValue(typeCount);
}

